import * as THREE from 'three/webgpu';
import { texture, MeshBasicNodeMaterial } from 'three/tsl';

const createNode = (config, ctx) => {
  // --- load texture synchronously ---
  const tex = ctx.textureLoader.load(config.assets.imageUrl);

  // --- apply atlas UV offsets if provided ---
  const region = config.atlasRegion;
  if (region && region.sourceRect) {
    const { x, y, width, height } = region.sourceRect;
    const atlasW = tex.image.naturalWidth || tex.image.width;
    const atlasH = tex.image.naturalHeight || tex.image.height;
    const repeatX = width / atlasW;
    const repeatY = height / atlasH;
    const offsetX = x / atlasW;
    // UV origin is bottom‑left; flip Y to match top‑left source rect
    const offsetY = 1 - (y + height) / atlasH;

    tex.repeat.set(repeatX, repeatY);
    tex.offset.set(offsetX, offsetY);
  }

  // --- geometry sized to the atlas region’s aspect ratio ---
  const regionWidth = region?.sourceRect?.width ?? tex.image.naturalWidth ?? 512;
  const regionHeight = region?.sourceRect?.height ?? tex.image.naturalHeight ?? 320;
  const aspect = regionWidth / regionHeight;
  const geo = new THREE.PlaneGeometry(1, 1 / aspect);

  // --- material with node based map ---
  const mat = new MeshBasicNodeMaterial();
  mat.map = texture(tex);

  // --- build the mesh ---
  const mesh = new THREE.Mesh(geo, mat);
  const pos = config.scenePlacement.position;
  const rot = config.scenePlacement.rotation;
  const scl = config.scenePlacement.scale;
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(rot.x, rot.y, rot.z);
  mesh.scale.set(scl.x, scl.y, scl.z);

  // --- billboard via update handler ---
  mesh.userData.handlers = {
    update: (camera) => {
      if (camera) {
        mesh.lookAt(camera.position);
      }
    },
  };

  // --- cleanup ---
  mesh.userData.cleanup = () => {
    geo.dispose();
    mat.dispose();
    tex.dispose();
    // no GSAP timelines in this node
  };

  return mesh;
};

export default createNode;
